// A simple Particle class
let Particle = function(position) {
	this.acceleration = createVector(0, gravity); //acceleration inits with no x axis and gravity y axis
	this.velocity = createVector(random(-1, 1), random(-1, 1)); //small init velocity
	this.position = position.copy(); //copy position (2d vector) from global var which is inited with emitter
	this.lifespan = life;//lifespan = slider
	this.bigness = size //size = slider
};

let forceField = class{
	constructor(pos, size, force, shows){
		this.position = pos;
		this.size = size;
		this.force = force;
		this.displays = shows;
	}
	display(){
		if(this.displays){
			if(scaling && currentCollider == this){
				fill(150, 150, 150, 10)
				noStroke()
			} else{
				fill(80, 80, 80, 30)
				noStroke()
			}
			circle(this.position.x,this.position.y,this.size)
		}
	}
}

Particle.prototype.run = function() {
	this.mouse(); //run the mouse code which moves particles away from mouse (includes updating particle velocity)
	this.update(); //handles pos and velocity update and lifespan
	this.display(); //displays circle at particle pos
	for(var field of fields){
		if(field.position.distSquared(this.position) < field.size ** 2){
			this.field(field);
			//print("In range" + random(1, 10))
		}
			field.display()
	}
};

Particle.prototype.mouse = function() {
	this.posRelativeToMouse = createVector( //gets difference between particle position and mouse pos
		this.position.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),
		this.position.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
	);
	this.distance = Math.sqrt( //sqrts the squares of both vectors added together
		this.posRelativeToMouse.x * this.posRelativeToMouse.x +
		this.posRelativeToMouse.y * this.posRelativeToMouse.y
	);
  this.forceDirection = createVector( //direction is the difference between mouse and particle position / distance
		this.posRelativeToMouse.x / this.distance,
		this.posRelativeToMouse.y / this.distance,
 	);
	maxDistance = MouseCloseness; //maxDistance = slider
	this.force = (maxDistance - this.distance)/maxDistance*MouseForce; //force is the scale of force which is determined by the sliders maxDistance and MouseForce
	if (this.force < 0) this.force = 0;
	this.vec = createVector(this.forceDirection.x * this.force,this.forceDirection.y * this.force)
  this.velocity.add(this.vec)
}

Particle.prototype.field = function(field) {
	var fieldX = field.position.x
	var fieldY = field.position.y
	var fieldSize = field.size/1.8
	var fieldForce= field.force
	this.posRelativeToField = createVector( //gets difference between particle position and mouse pos
		this.position.x - fieldX,
		this.position.y - fieldY
	);
	this.distance = Math.sqrt( //sqrts the squares of both vectors added together
		this.posRelativeToField.x * this.posRelativeToField.x +
		this.posRelativeToField.y * this.posRelativeToField.y
	);
  this.forceDirection = createVector( //direction is the difference between mouse and particle position / distance
		this.posRelativeToField.x / this.distance,
		this.posRelativeToField.y / this.distance,
 	);
	maxDistance = fieldSize; //maxDistance = slider
	this.force = (maxDistance - this.distance)/maxDistance*fieldForce; //force is the scale of force which is determined by the sliders maxDistance and MouseForce
	if (this.force < 0) this.force = 0;
	this.vec = createVector(this.forceDirection.x * this.force,this.forceDirection.y * this.force)
  this.velocity.add(this.vec)
}

Particle.prototype.posupdate = function() {
	//let angle = Math.atan(y2-y1, x2-x1)*180/PI
	/*if(isInside(x1,y1,x2,y2,x3,y3,this.position.x,this.position.y)){
		this.velocity = createVector((this.velocity.x+angle)/100,(-this.velocity.y*bounciness)/10)
		this.position.add(this.velocity)
		print(angle)
	}*/
	this.position.add(this.velocity)
	if(this.position.y+this.bigness/1.5>windowHeight){
		if(BounceWalls == false){
			this.lifespan = 0
		}
		else {
			this.velocity.y = -this.velocity.y/bounciness
		}
	}
	if(this.position.x+this.bigness/1.5>windowWidth){
		if(BounceWalls == false){
			this.lifespan = 0
		}
		else {
			this.velocity.x = -this.velocity.x/bounciness
		}
	}
	if(NoTopBounds == false){
		if(this.position.y-this.bigness/1.5<0){
			if(BounceWalls == false){
				this.lifespan = 0
			}
			else {
				this.velocity.y = -this.velocity.y/bounciness
			}
		}	
	}
	if(this.position.x-this.bigness/1.5<0){
		if(BounceWalls == false){
			this.lifespan = 0
		}
		else {
			this.velocity.x = -this.velocity.x/bounciness
		}
	}
}


// Method to update position
Particle.prototype.update = function() {
	this.velocity.add(this.acceleration);
	this.posupdate()
	if(InfiniteLife == false){
		this.lifespan -= 2;
	}
	if(this.bigness>minimum_size){
	this.bigness -= size_decay;
	system.origin = createVector(EmitterX, EmitterY);
	} else {
		this.lifespan = 0
	}
};

// Method to display
Particle.prototype.display = function() {
	stroke(200, this.lifespan);
	strokeWeight(0.001);
	fill(random(this.lifespan* 255 + life_color_offset, this.lifespan * 256 + life_color_offset), this.lifespan/4 + life_color_offset/4, this.lifespan/8 + life_color_offset/8, this.lifespan);
	circle(this.position.x, this.position.y, this.bigness);
};

// Is the particle still useful?
Particle.prototype.isDead = function() {
	return this.lifespan < 0;
};


let ParticleSystem = function(position) {
	this.origin = position.copy();
	this.particles = [];
};

ParticleSystem.prototype.addParticle = function(x,y) {
	if(x==y){
		this.particles.push(new Particle(this.origin));
		FrameCount = 0
	}
};

ParticleSystem.prototype.run = function() {
	for (let i = this.particles.length - 1; i >= 0; i--) {
		let p = this.particles[i];
		p.run();
		if (p.isDead()) {
			delete this.particles[i]
			this.particles.splice(i, 1);
		}
	}
};
